example_item.example_item_data:
% The whole analysis of a simulated twelve-lead record in one call.
recording = ecglab.simulate('Seconds', 60, 'Leads', 12, 'Seed', 1);
analysis = ecglab.analyze(recording);
analysis.summary.heartRate.mean

% Run only the beat detection and the variability, and see the rest noted.
recording = ecglab.simulate('Seconds', 300, 'HeartRateStd', 5, 'Seed', 1);
analysis = ecglab.analyze(recording, 'Do', {'detect', 'hrv'});
analysis.summary.hrv
analysis.notes
